  const OV_A1 = 0.33, OV_F = 0.594;          // дом в чертёж трогается на 33 % ухода фона (было 63 %, потом 45 %); фасад — на 59 % первой фазы
  const PH = 0.56 * (P0.f[1] - P0.f[0]);     // фаза фасада (дом или окружение) в прежнем темпе, 1,568 с
  const bD = (P0.b[1] - P0.b[0]) * K_A1, hD = (P0.h[1] - P0.h[0]) * K_A1, h0 = OV_A1 * bD;
  const o0 = h0 + hD - (P0.h[1] - P0.o[0]), oD = P0.o[1] - P0.o[0];          // облёт трогается, пока дом досаживается (0,09 с), как было
